    public void handle( CreateFacilityEvent event) {
	    LOGGER.info("handling CreateFacilityEvent - " + event );
	    Facility entity = new Facility();
            entity.setFacilityId( event.getFacilityId() );
            entity.setName( event.getName() );
            entity.setFacilityCode( event.getFacilityCode() );
            entity.setAddress( event.getAddress() );
            entity.setFacilityType( event.getFacilityType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllFacility( entity );
    }

