    /**
     * Method to retrieve the Facility via an FacilityPrimaryKey.
     * @param 	id Long
     * @return 	Facility
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Facility handle( FindFacilityQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getFacilityId() );
    }
    
    /**
     * Method to retrieve a collection of all Facilitys
     *
     * @param	query	FindAllFacilityQuery 
     * @return 	List<Facility> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Facility> handle( FindAllFacilityQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindFacility,
 * but only if the id matches
 *
 * @param		entity	Facility
 */
	protected void emitFindFacility( Facility entity ) {
		LOGGER.info("handling emitFindFacility" );
		
	    queryUpdateEmitter.emit(FindFacilityQuery.class,
	                            query -> query.getFilter().getFacilityId().equals(entity.getFacilityId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFacility
	 * 
	 * @param		entity	Facility
	 */
	protected void emitFindAllFacility( Facility entity ) {
		LOGGER.info("handling emitFindAllFacility" );
		
	    queryUpdateEmitter.emit(FindAllFacilityQuery.class,
	                            query -> true,
	                            entity);
	}

